use std::fs
use std::env

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if names.len() == 0 {
        names.push("/dev/stdin")
    }
    for name in names {
        let mut content = ""
        match fs::read_to_string(name) {
            Ok(c) => { content = c }
            Err(_) => {
                println("cat: ${name}: No such file")
                status = 1
                continue
            }
        }
        if number {
            for line in content.lines() {
                counter += 1
                println("${counter:>6}\t${line}")
            }
        } else {
            print("${content}")
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}
